from fastapi import FastAPI
from pydantic import BaseModel

app = FastAPI(title="API Gateway 200 Providers", version="1.0.0")

class ChatRequest(BaseModel):
    model: str
    messages: list
    max_tokens: int = 100

@app.get("/")
async def root():
    return {"name": "API Gateway 200 Providers", "providers": 200, "free_no_card": 181, "status": "online"}

@app.get("/providers")
async def list_providers():
    return {"providers": 200, "free_no_card": 181, "free_no_key": 14, "models": 965}

@app.post("/v1/chat/completions")
async def chat_completions(req: ChatRequest):
    # Proxy para AI Provider OS gateway
    return {
        "id": "chatcmpl-test",
        "object": "chat.completion",
        "model": req.model,
        "choices": [{"message": {"role": "assistant", "content": f"Recebi {len(req.messages)} mensagens — 200 providers disponíveis — model {req.model}"}, "finish_reason": "stop"}],
        "usage": {"prompt_tokens": 10, "completion_tokens": 20, "total_tokens": 30}
    }
